#!/usr/bin/env bash
set -euo pipefail
BUNDLE_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; GAME_URL=https://play.91hwl.cn/moyu/; VERSION_URL=https://play.91hwl.cn/moyu/VERSION; ORIGIN=play.91hwl.cn:443:127.0.0.1
fail(){ echo "MOYU_HEALTHCHECK_ERROR: $*" >&2; exit 1; }
version="$(tr -d '\r\n' < "$BUNDLE_ROOT/VERSION")"; revision="$(tr -d '\r\n' < "$BUNDLE_ROOT/REVISION")"; work="$(mktemp -d /tmp/moyu-health.XXXXXX)"; trap 'rm -rf -- "$work"' EXIT
probe(){ prefix="$1"; shift; curl -fsSL --noproxy '*' "$@" -o "$work/$prefix.html"; grep -Fq '<meta name="version" content="1.25.0"' "$work/$prefix.html"; grep -Fq 'style.css?v=1250' "$work/$prefix.html"; grep -Fq 'visual-v1113.css?v=1250' "$work/$prefix.html"; grep -Fq 'responsive-v1120.css?v=1250' "$work/$prefix.html"; grep -Fq 'game.js?v=1250' "$work/$prefix.html"; grep -Fq 'translate="no"' "$work/$prefix.html"; grep -Fq "(cl==='zh'||cl==='en')?cl:((sl==='zh'||sl==='en')?sl:bl)" "$work/$prefix.html"; ! grep -Fq "c('91hwl_lang')||localStorage.getItem('91hwl_lang')||" "$work/$prefix.html"; grep -Fq 'id="lastRunSummary"' "$work/$prefix.html"; grep -Fq 'id="topRunHistory"' "$work/$prefix.html"; grep -Fq 'id="dailyBtn"' "$work/$prefix.html"; grep -Fq 'id="dailyBadge"' "$work/$prefix.html"; }
probe origin --resolve "$ORIGIN" "$GAME_URL" || fail 'origin HTML/prepaint check failed'
curl -fsSL --noproxy '*' --resolve "$ORIGIN" "https://play.91hwl.cn/moyu/style.css?v=1250" -o "$work/base.css" || fail 'origin base CSS missing'; grep -Fq '.run-ledger-grid' "$work/base.css" || fail 'run ledger layout missing'; grep -Fq 'playfield-first presentation' "$work/base.css" || fail 'playfield-first CSS missing'; grep -Fq 'v1.15.0 experience pass' "$work/base.css" || fail 'experience CSS missing'; grep -Fq 'height:min(54svh,440px)' "$work/base.css" || fail 'portrait playfield height missing'; grep -Fq 'left:clamp(-28px,-7vw,-18px)' "$work/base.css" || fail 'portrait camera lead missing';
curl -fsSL --noproxy '*' --resolve "$ORIGIN" "https://play.91hwl.cn/moyu/visual-v1113.css?v=1250" -o "$work/visual.css" || fail 'origin visual CSS missing'; grep -Fq 'font-size:17px' "$work/visual.css" || fail 'result body readability rule missing'; grep -Fq 'font-size:14.5px' "$work/visual.css" || fail 'result control readability rule missing'; grep -Fq 'height:44px' "$work/visual.css" || fail 'top control scale missing'
curl -fsSL --noproxy '*' --resolve "$ORIGIN" "https://play.91hwl.cn/moyu/responsive-v1120.css?v=1250" -o "$work/responsive.css" || fail 'origin responsive CSS missing'; grep -Fq 'env(safe-area-inset-bottom)' "$work/responsive.css" || fail 'mobile safe-area rule missing'; grep -Fq '@media(max-width:560px)' "$work/responsive.css" || fail 'narrow phone breakpoint missing'; grep -Fq '.home-link::before' "$work/responsive.css" || fail 'narrow header compaction missing'; grep -Fq '@media(max-width:700px) and (orientation:portrait)' "$work/responsive.css" || fail 'portrait viewport rule missing'; grep -Fq 'padding-left:max(2px,env(safe-area-inset-left))' "$work/responsive.css" || fail 'portrait width expansion missing'
curl -fsSL --noproxy '*' --resolve "$ORIGIN" "https://play.91hwl.cn/moyu/assets/sprites/hero-v125.webp?v=1250" -o "$work/hero-v125.webp" || fail 'origin hero v1.25 sprite missing'; test "$(sha256sum "$work/hero-v125.webp" | awk '{print $1}')" = '5db0e3363678341f6f432d7366c0670bc5a0f42be87417d1c43273710364db37' || fail 'origin hero v1.25 sprite checksum mismatch'
curl -fsSL --noproxy '*' --resolve "$ORIGIN" "https://play.91hwl.cn/moyu/assets/sprites/scene-backdrops-v125.webp?v=1250" -o "$work/scene-backdrops-v125.webp" || fail 'origin scene backdrop v1.25 missing'; test "$(sha256sum "$work/scene-backdrops-v125.webp" | awk '{print $1}')" = '21bba4b6ddd0dd8736bbb879ee5b10a5063aea18a25e1c979c550d16bd8b9584' || fail 'origin scene backdrop v1.25 checksum mismatch'
curl -fsSL --noproxy '*' --resolve "$ORIGIN" "https://play.91hwl.cn/moyu/assets/sprites/office-hazards-v124.webp?v=1240" -o "$work/office-hazards.webp" || fail 'origin office hazard atlas missing'; test "$(sha256sum "$work/office-hazards.webp" | awk '{print $1}')" = '93b2583d42dc79a999ddf7f1761067eb9b516249193bbc33412b9bcd8be9ff56' || fail 'origin office hazard atlas checksum mismatch'
curl -fsSL --noproxy '*' --resolve "$ORIGIN" "https://play.91hwl.cn/moyu/game.js?v=1250" -o "$work/game.js" || fail 'origin JS missing'; grep -Fq "dataset.gameVersion='1.25.0'" "$work/game.js" || fail 'runtime version mismatch'; grep -Fq 'function syncBuffHud()' "$work/game.js" || fail 'buff HUD runtime missing'; grep -Fq 'function pickupGrabBox(p)' "$work/game.js" || fail 'pickup forgiveness missing'; grep -Fq 'LEAVE_SLIP_DURATION=12' "$work/game.js" || fail 'leave-slip duration mismatch'; grep -Fq 'assets/sprites/office-hazards-v124.webp?v=1240' "$work/game.js" || fail 'office hazard atlas runtime missing'; grep -Fq 'function drawOfficeHazardFrame(name,dx,dy,dw,dh,alpha=1,flipX=false)' "$work/game.js" || fail 'office hazard atlas renderer missing'; grep -Fq 'debugHazardAtlas' "$work/game.js" || fail 'office hazard debug hook missing'; grep -Fq 'assets/sprites/hero-v125.webp?v=1250' "$work/game.js" || fail 'hero sprite runtime missing'; grep -Fq 'assets/sprites/scene-backdrops-v125.webp?v=1250' "$work/game.js" || fail 'scene backdrop runtime missing'; grep -Fq 'function drawAuthenticScene(idx)' "$work/game.js" || fail 'scene backdrop renderer missing'; grep -Fq 'function drawAssetRunway()' "$work/game.js" || fail 'collision runway renderer missing'; grep -Fq 'debugSceneBackdrop' "$work/game.js" || fail 'scene backdrop debug hook missing'; grep -Fq 'function applyEncounterCadence(gapPx,plan)' "$work/game.js" || fail 'encounter cadence missing'; grep -Fq 'visualScrollPx+=speed*dt' "$work/game.js" || fail 'physical visual scroll missing'; grep -Fq 'display:112' "$work/game.js" || fail 'runner visual scale mismatch'; ! grep -Fq "drawW=frameIndex===HERO_SPRITE.doubleJump?108:size" "$work/game.js" || fail 'legacy double-jump width compensation remains'; grep -Fq 'MUSIC_PHRASE_STEPS=256' "$work/game.js" || fail 'long-form music suite missing'; grep -Fq "langBtn.blur()" "$work/game.js" || fail 'language focus release missing'; grep -Fq "jumpKey&&state==='playing'" "$work/game.js" || fail 'gameplay jump priority missing'; grep -Fq "if(tutorialActive&&tutorialStep)setTutorial(tutorialStep)" "$work/game.js" || fail 'live tutorial relocalization missing'; grep -Fq "storedNumber('91hwl_moyu_music_vol',42)" "$work/game.js" || fail 'music default mismatch'; grep -Fq "storedNumber('91hwl_moyu_sfx_vol',72)" "$work/game.js" || fail 'sfx default mismatch'; grep -Fq 'v1.22 English composition' "$work/visual.css" || fail 'English composition missing'; grep -Fq "name:'工位区 · 午后摸鱼'" "$work/game.js" || fail 'workstation soundtrack missing'; grep -Fq "name:'会议室 · 偷偷走神'" "$work/game.js" || fail 'meeting soundtrack missing'; grep -Fq "name:'茶水间 · 咖啡续杯'" "$work/game.js" || fail 'pantry soundtrack missing'; grep -Fq "name:'健身房 · 下班冲刺'" "$work/game.js" || fail 'gym soundtrack missing'; grep -Fq "if(raw===null||raw==='')return fallback" "$work/game.js" || fail 'fresh audio defaults missing'; grep -Fq "o.rush&&!o.rushTriggered&&o.x<610" "$work/game.js" || fail 'boss warning timing mismatch'; grep -Fq "unlockDiscovery(def.discovery,true)" "$work/game.js" || fail 'rare event dedupe missing'; grep -Fq 'JUMP_GRAVITY=1750' "$work/game.js" || fail 'jump timing retune missing'; ! grep -Fq 'spawnPickupChoice' "$work/game.js" || fail 'retired route-choice experiment remains'; grep -Fq 'sceneComboRecoveryUsed' "$work/game.js" || fail 'combo recovery state missing'; grep -Fq 'MAX_MISTAKES=3' "$work/game.js" || fail 'three-strike buffer missing'; grep -Fq 'function takeObstacleHit(o)' "$work/game.js" || fail 'forgiving collision handler missing'; grep -Fq 'id="mistakeChip"' "$work/origin.html" || fail 'mistake HUD missing'; grep -Fq 'groundTakeoff=before===0' "$work/game.js" || fail 'ground-only jump dust guard missing'; grep -Fq 'writeSharedLangCookie(currentLang)' "$work/game.js" || fail 'shared language bridge missing'; grep -Fq 'const storedLang=storageGet(LANG_KEY)' "$work/game.js" || fail 'stored language validation missing'; grep -Fq "(storedLang==='en'||storedLang==='zh')?storedLang:browserLang" "$work/game.js" || fail 'stored language fallback missing'; ! grep -Fq "storageGet(LANG_KEY)||(navigator.language||'zh').toLowerCase().startsWith('zh')?'zh':'en'" "$work/game.js" || fail 'ambiguous language precedence remains'; grep -Fq 'repeatSensitiveKeys' "$work/game.js" || fail 'repeat-input guard missing'; grep -Fq 'canvasLayoutDirty' "$work/game.js" || fail 'canvas layout guard missing'; grep -Fq 'syncPresentationState.signature' "$work/game.js" || fail 'presentation memoization missing'; grep -Fq 'function viewportFrameMaxWidth' "$work/game.js" || fail 'viewport frame calculator missing'; grep -Fq 'function fitGameFrameToViewport' "$work/game.js" || fail 'viewport-first frame fitting missing'; grep -Fq 'function choosePickupKind' "$work/game.js" || fail 'risk pickup router missing'; grep -Fq 'function nearMissTier' "$work/game.js" || fail 'near-miss scoring route missing'; grep -Fq 'function absorbWithLeaveSlip' "$work/game.js" || fail 'leave-slip safety route missing'; grep -Fq 'meetingDrift=sceneIndex===1&&!first' "$work/game.js" || fail 'meeting scene action missing'; grep -Fq 'gymBounce=true' "$work/game.js" || fail 'gym scene action missing'; grep -Fq 'function recordFinishedRun' "$work/game.js" || fail 'run record writer missing'; grep -Fq 'function renderRunLedger' "$work/game.js" || fail 'run ledger renderer missing'; grep -Fq '91hwl_moyu_top_runs' "$work/game.js" || fail 'top-run storage missing'; grep -Fq 'function gameRandom()' "$work/game.js"; grep -Fq 'function drawGameFeelFx()' "$work/game.js"; grep -Fq 'function updateComboHud()' "$work/game.js"; grep -Fq 'BOSS_RUSH_WARNING=.48' "$work/game.js" || fail 'daily PRNG missing'; grep -Fq 'function setDailyMode(enabled)' "$work/game.js" || fail 'daily mode switch missing'; grep -Fq 'dailyModifierDefs' "$work/game.js" || fail 'daily modifiers missing'; grep -Fq 'effectiveSpawnWidth(spawned)' "$work/game.js" || fail 'long BUG gap reserve missing'; grep -Fq 'const rise=airborne' "$work/game.js" || fail 'velocity-driven runner pose missing'; grep -Fq 'const cadence=10.5' "$work/game.js" || fail 'runner gait cadence missing'; grep -Fq 'assets/sprites/hero-v125.webp?v=1250' "$work/game.js" || fail 'hero sprite runtime missing'; grep -Fq 'function heroRunFrameStep()' "$work/game.js" || fail 'runner gait limiter missing'; grep -Fq 'player.jumps>=2&&airBurstTimer>0' "$work/game.js" || fail 'double-jump sprite state missing'; grep -Fq 'function drawPlayerSprite()' "$work/game.js" || fail 'hero sprite renderer missing'; grep -Fq 'RUN_PROGRESS_SCALE=.020' "$work/game.js" || fail 'four-minute progression scale missing'; grep -Fq 'function drawWorkstationLife(pod)' "$work/game.js" || fail 'workstation life layer missing'; grep -Fq 'function drawMeetingLife(module)' "$work/game.js" || fail 'meeting life layer missing'; grep -Fq 'function drawPantryLife(pod)' "$work/game.js" || fail 'pantry life layer missing'; grep -Fq 'function drawGymLife(pod)' "$work/game.js" || fail 'gym life layer missing'; grep -Fq 'function drawBossArt(o)' "$work/game.js" || fail 'boss art renderer missing'; grep -Fq 'function drawBugArt(o)' "$work/game.js" || fail 'bug art renderer missing'; grep -Fq 'function drawRequestArt(o)' "$work/game.js" || fail 'request art renderer missing'; grep -Fq 'function drawSmallHazardArt(o)' "$work/game.js" || fail 'small hazard art renderer missing'; grep -Fq 'Three subtle motion planes' "$work/game.js" || fail 'motion depth layer missing'; ! grep -Fq 'drawPlayerFocus(drawX,footY,altitude);' "$work/game.js" || fail 'player halo still active'; ! grep -Fq 'drawBackground();drawAmbientOfficeLife();drawRunAtmosphere();' "$work/game.js" || fail 'drifting ambient coworkers still active'
actual="$(curl -fsSL --noproxy '*' --resolve "$ORIGIN" "$VERSION_URL" | tr -d '\r\n[:space:]')"; test "$actual" = "$version" || fail 'origin VERSION mismatch'
# Both explicit language routes must keep the same validated prepaint selector and v1.25.0 assets.
for lang in zh en; do curl -fsSL --noproxy '*' --resolve "$ORIGIN" "${GAME_URL}?lang=$lang&release=$revision" -o "$work/$lang.html" || fail "origin $lang route failed"; grep -Fq 'game.js?v=1250' "$work/$lang.html" || fail "$lang route asset mismatch"; grep -Fq 'responsive-v1120.css?v=1250' "$work/$lang.html" || fail "$lang responsive asset mismatch"; grep -Fq "(cl==='zh'||cl==='en')?cl:((sl==='zh'||sl==='en')?sl:bl)" "$work/$lang.html" || fail "$lang validated prepaint selector missing"; done
public_ok=false; for i in 1 2 3 4 5 6; do if probe public "${GAME_URL}?release=$revision" && test "$(curl -fsSL "${VERSION_URL}?release=$revision" | tr -d '\r\n[:space:]')" = "$version"; then public_ok=true; break; fi; sleep 2; done; test "$public_ok" = true || fail 'public Moyu check failed'
curl -fsSL --noproxy '*' --resolve "$ORIGIN" https://play.91hwl.cn/dungeon-echo/ -o /dev/null || fail 'Dungeon Echo preservation check failed'
echo "public_url=$GAME_URL"; echo "public_version=$version"; echo 'moyu_healthcheck=PASS'
